insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$altinopolis$q$, $q$https://altinopolis.siscam.com.br/Documentos/Documento/2110 (LC 97/2017; PDF https://altinopolis.siscam.com.br/arquivo?Id=2117) ; https://altinopolis.siscam.com.br/Documentos/Documento/1636 (Lei 1.633/2009)$q$, $q$Atos oficiais de Altinópolis: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0); vias do registro desativado: OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 6, $q$LC 97/2017: articulados, veículos de carga e de grande porte proibidos em todo o perímetro urbano, 24 h; exceções para entrega/carregamento no perímetro com nota fiscal, emplacados em Altinópolis e motoristas residentes, e AET mediante cadastro. A Lei 1.633/2009, art. 3º (5 ruas centrais, fim de semana à noite), fica desativada (vigência incerta).$q$);
